  "d": "Asthma",
  "ans": "B",
  "e": "Lifestyle modification is first-line for mild GORD; weight loss, head elevation, dietary changes, and smoking cessation reduce symptoms.<br><br>Avoid trigger foods (chocolate, caffeine, alcohol, citrus, fatty foods). Avoid eating within 3 hours of bedtime. Elevate head of bed by 6-8 inches. Combined with PPI therapy for moderate-severe disease. Surgical fundoplication for refractory or complicated disease.<br><br>Surgery first (option A) is for refractory; high-dose PPI lifelong (option C) is for severe; observation only (option D) misses opportunity, distinct from lifestyle modification mild GORD first-line approach.<br><br><em>(First Aid for USMLE Step 1)</em>"
