  "e": "Barrett's oesophagus is intestinal metaplasia confirmed on biopsy; chronic GORD produces columnar epithelium replacing squamous epithelium.<br><br>Endoscopy with biopsy confirms diagnosis. Surveillance endoscopy every 3-5 years for non-dysplastic Barrett's. Endoscopic eradication for high-grade dysplasia and intramucosal cancer. Surgical resection for invasive cancer. PPI therapy controls reflux symptoms but does not reverse metaplasia. Standard supportive care guides management.<br><br>GORD without metaplasia (option B) lacks columnar epithelium; achalasia (option C) is motility; oesophageal cancer (option D) is malignant, distinct from Barrett's intestinal metaplasia premalignant condition.<br><br><em>(First Aid for USMLE Step 1)</em>"
