  "e": "Bile acid diarrhoea follows ileal resection; loss of terminal ileum reduces bile acid reabsorption.<br><br>Treatment with bile acid sequestrants (cholestyramine, colesevelam) reduces diarrhoea. Combined with addressing underlying Crohn or other cause. Multidisciplinary team optimises decisions. Long-term follow-up is essential. Patient education supports self-management. Distinguishing from active Crohn through SeHCAT scan or empirical trial. Long-term follow-up is essential.<br><br>Pancreatic insufficiency (option B) features steatorrhoea; lactose intolerance (option C) is enzyme; coeliac disease (option D) is gluten, distinct from bile acid diarrhoea ileal-resection terminal-ileum-dependence mechanism.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
