  "ans": "A",
  "e": "Pancreatic ductal adenocarcinoma is most common pancreatic cancer; ductal epithelium origin produces 85-90 percent of pancreatic cancers.<br><br>Risk factors include smoking, chronic pancreatitis, family history, BRCA mutations, and Lynch syndrome. CT abdomen with pancreatic protocol confirms diagnosis. Treatment includes Whipple resection for resectable disease, palliative therapy with chemotherapy for advanced disease. Multidisciplinary team optimises decisions. Long-term follow-up is essential.<br><br>Neuroendocrine tumour (option B) is uncommon; acinar cell carcinoma (option C) is rare; cystic neoplasm (option D) is uncommon, distinct from ductal adenocarcinoma most common pancreatic cancer.<br><br><em>(First Aid for USMLE Step 1)</em>"
