  "e": "Endoscopic band ligation is first-line for active variceal bleeding; rubber bands occlude varices producing thrombosis.<br><br>Combined with vasoactive therapy (terlipressin, somatostatin, octreotide) for acute bleeding. Antibiotic prophylaxis (ceftriaxone) reduces infection. TIPS for refractory bleeding. Long-term programme with serial banding obliterates varices. Multidisciplinary team optimises decisions. Patient education supports self-management. Standard supportive care guides management.<br><br>Sclerotherapy alone (option A) is alternative; balloon tamponade alone (option B) is temporary; TIPS first (option C) is for refractory, distinct from band ligation active variceal bleeding first-line endoscopic.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
