  "e": "Non-selective beta-blockers reduce variceal bleeding risk; propranolol and nadolol reduce portal pressure through splanchnic vasoconstriction.<br><br>Standard dose propranolol 20 mg twice daily titrated to heart rate target 55-60/min. Carvedilol alternative with additional alpha-blockade. Indications include primary prophylaxis in moderate-large varices and secondary prophylaxis combined with band ligation. Multidisciplinary team optimises decisions. Endoscopic surveillance detects early changes.<br><br>Calcium channel blockers (option A) lack benefit; loop diuretics (option C) treat ascites; ACE inhibitors (option D) lack proven benefit, distinct from non-selective beta-blocker variceal pressure reduction prophylaxis.<br><br><em>(Davidson's Principles and Practice of Medicine)</em>"
